<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>    <div class="mainbox">        <div id="nav" class="mainnav_title">            <ul>                <a href="{pigcms{:U('Merchant/spread_merchant',array('mer_id'=>$_GET['mer_id']))}" class="on">【{pigcms{$merchant_info['name']}】下级推广商家列表</a>            </ul>        </div>        <table class="search_table" width="100%">            <tr>                <td style="width:60%;">                    <form action="{pigcms{:U('Merchant/recommend_index')}" method="get">                        <input type="hidden" name="c" value="Merchant"/>                        <input type="hidden" name="a" value="recommend_index"/>                        筛选:                        <if condition="$admin_area neq 3">                        <div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>                        </if>                        <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                        <select name="searchtype">                            <option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>商家名称</option>                            <option value="store" <if condition="$_GET['searchtype'] eq 'store'">selected="selected"</if>>店铺名称</option>                            <option value="account" <if condition="$_GET['searchtype'] eq 'account'">selected="selected"</if>>商家帐号</option>                            <option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>联系电话</option>                            <option value="mer_id" <if condition="$_GET['searchtype'] eq 'mer_id'">selected="selected"</if>>商家编号</option>                        </select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                        商家状态: <select name="searchstatus">                            <option value="0" <if condition="$_GET['searchstatus'] eq 0">selected="selected"</if>>正常</option>                            <option value="1" <if condition="$_GET['searchstatus'] eq '1'">selected="selected"</if>>待审核</option>                            <option value="2" <if condition="$_GET['searchstatus'] eq '2'">selected="selected"</if>>关闭</option>                            <option value="3" <if condition="$_GET['searchstatus'] eq '3'">selected="selected"</if>>全部</option>                        </select>                        排序: <select name="searchorder">                            <option value="0" <if condition="$_GET['searchorder'] eq 0">selected="selected"</if>>商家ID</option>                            <option value="1" <if condition="$_GET['searchorder'] eq '1'">selected="selected"</if>>商家余额</option>                        </select>                        <input type="submit" value="查询" class="button"/>                    </form>                </td>            </tr>        </table>            <div class="table-list">                <table width="100%" cellspacing="0">                    <colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>                    <thead>                        <tr>                            <th>编号</th>                            <th>商家名称</th>                            <if condition="!isset($config['not_o2o_demo'])">                            <th>联系电话</th>                            </if>                            <th>获得商家佣金（元）</th>                            <th class="textcenter">操作</th>                        </tr>                    </thead>                    <tbody>                        <if condition="is_array($merchant_list)">                            <volist name="merchant_list" id="vo">                                <tr>                                    <td>{pigcms{$vo.mer_id}</td>                                    <td>{pigcms{$vo.name}</td>                                    <if condition="!isset($config['not_o2o_demo'])">                                    <td>{pigcms{$vo.phone}</td>                                    </if>                                    <td>{pigcms{$vo.all_spread_money}</td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="12">列表为空！</td></tr>                        </if>                    </tbody>                </table>            </div>    </div><include file="Public:footer"/>